40	static void internalBodySetMass(cpBody *body, cpFloat mass)
41	{
42	    cpBodyActivate(body);
43	    body->m = mass;
44	    body->m_inv = 1.0f/mass;
45	    //cpAssertSaneBody(body);
46	}
47	
48	static void internalBodyUpdateVelocity(cpBody *body, cpVect gravity, cpFloat damping, cpFloat dt)
49	{
50	    cpBodyUpdateVelocity(body, cpvzero, damping, dt);
51	    // Skip kinematic bodies.
52	    if(cpBodyGetType(body) == CP_BODY_TYPE_KINEMATIC) return;
53	    
54	    cpAssertSoft(body->m > 0.0f && body->i > 0.0f, "Body's mass and moment must be positive to simulate. (Mass: %f Moment: f)", body->m, body->i);
55	    
56	    cocos2d::PhysicsBody *physicsBody = static_cast<cocos2d::PhysicsBody*>(body->userData);
57	    
58	    if(physicsBody->isGravityEnabled())
59	            body->v = cpvclamp(cpvadd(cpvmult(body->v, damping), cpvmult(cpvadd(gravity, cpvmult(body->f, body->m_inv)), dt)), physicsBody->getVelocityLimit());
60	    else
61	            body->v = cpvclamp(cpvadd(cpvmult(body->v, damping), cpvmult(cpvmult(body->f, body->m_inv), dt)), physicsBody->getVelocityLimit());
62	    cpFloat w_limit = physicsBody->getAngularVelocityLimit();
63	    body->w = cpfclamp(body->w*damping + body->t*body->i_inv*dt, -w_limit, w_limit);
64	    
65	    // Reset forces.
66	    body->f = cpvzero;
67	    //to check body sanity
68	    cpBodySetTorque(body, 0.0f);
69	}
