404	PhysicsShape* PhysicsBody::addShape(PhysicsShape* shape, bool addMassAndMoment/* = true*/)
405	{
406	    if (shape == nullptr) return nullptr;
407	
408	    // add shape to body
409	    if (_shapes.getIndex(shape) == -1)
410	    {
411	        shape->setBody(this);
412	
413	        // calculate the area, mass, and density
414	        // area must update before mass, because the density changes depend on it.
415	        if (addMassAndMoment)
416	        {
417	            _area += shape->getArea();
418	            addMass(shape->getMass());
419	            addMoment(shape->getMoment());
420	        }
421	
422	        if (_world != nullptr)
423	        {
424	            _world->addShape(shape);
425	        }
426	
427	        _shapes.pushBack(shape);
428	    }
429	
430	    return shape;
431	}
