491	void PhysicsBody::addMass(float mass)
492	{
493	    if (mass == PHYSICS_INFINITY)
494	    {
495	        _mass = PHYSICS_INFINITY;
496	        _massDefault = false;
497	        _density = PHYSICS_INFINITY;
498	    }
499	    else if (mass == -PHYSICS_INFINITY)
500	    {
501	        return;
502	    }
503	    else
504	    {
505	        if (_massDefault)
506	        {
507	            _mass = 0;
508	            _massDefault = false;
509	        }
510	
511	        if (_mass + mass > 0)
512	        {
513	            _mass += mass;
514	        }
515	        else
516	        {
517	            _mass = MASS_DEFAULT;
518	            _massDefault = true;
519	        }
520	
521	        if (_area > 0)
522	        {
523	            _density = _mass / _area;
524	        }
525	        else
526	        {
527	            _density = 0;
528	        }
529	    }
530	
531	    // the static body's mass and moment is always infinity
532	    if (_dynamic)
533	    {
534	        internalBodySetMass(_cpBody, _mass);
535	    }
536	}
