676	void PhysicsBody::removeShape(PhysicsShape* shape, bool reduceMassAndMoment/* = true*/)
677	{
678	    if (_shapes.getIndex(shape) != -1)
679	    {
680	        if (reduceMassAndMoment)
681	        {
682	            _area -= shape->getArea();
683	            _mass = std::max(0.0f, _mass - shape->getMass());
684	            _moment = std::max(0.0f, _moment - shape->getMoment());
685	        }
686	        shape->_body = nullptr;
687	        shape->setBody(nullptr);
688	        _shapes.eraseObject(shape);
689	    }
690	}
