868	        setScale(scaleX, scaleY);
869	    }
870	
871	    // set rotation
872	    if (_recordedRotation != rotation)
873	    {
874	        setRotation(rotation);
875	    }
876	
877	    // set position
878	    auto worldPosition = _ownerCenterOffset;
879	    nodeToWorldTransform.transformPoint(&worldPosition);
880	    setPosition(worldPosition.x, worldPosition.y);
881	
